    vector<string> reorderLogFiles(vector<string>& logs) {
        vector<string> wordsSide;
        vector<string> numsSide;

        for (string s : logs) {
            size_t gap = s.find(' ');
            string rest = s.substr(gap + 1);
            bool isNum = false;
            if (!rest.empty() && rest[0] >= '0' && rest[0] <= '9') isNum = true;

            if (isNum) numsSide.push_back(s);
            else wordsSide.push_back(s);
        }

        sort(wordsSide.begin(), wordsSide.end(), [](const string& left, const string& right) {
            size_t p1 = left.find(' ');
            size_t p2 = right.find(' ');

            string a_id = left.substr(0, p1);
            string b_id = right.substr(0, p2);
            string a_body = left.substr(p1 + 1);
            string b_body = right.substr(p2 + 1);

            if (a_body == b_body) return a_id < b_id;
            return a_body < b_body;
        });

        vector<string> arranged;
        arranged.reserve(logs.size());

        for (auto &x : wordsSide) arranged.push_back(x);
        for (auto &x : numsSide) arranged.push_back(x);

        return arranged;
    }
};

