        unordered_map<string, int> g_score;

        g_score[start] = 0;
        pq.emplace(getH(start), 0, start);

        while (!pq.empty()) {
            auto [f, g, curr] = pq.top();
            pq.pop();

            if (curr == target) return g;
            if (g > g_score[curr]) continue;

            int zero_pos = curr.find('0');
            for (int next_pos : neighbors[zero_pos]) {
